      "endpoint_type": "total_organofluorine_change",
      "evidence_locator_ids": [
        "S07-E01",
        "S07-E02",
        "S07-E03",
        "S07-E06"
      ],
      "interpretation": "AOF was measured in influent and effluent and compared (in moles of fluorine) to six dominant PFAS and to fluoride to establish an organic-fluorine mass balance. The total decrease in AOF-defined organofluorine exceeded the increase in fluoride, indicating incomplete closure of the fluorine mass balance and suggesting transformation to other unmeasured organofluorine species or analytical gaps (e.g., ultrashort PFAS).",
      "reported_term": "Decrease in adsorbable organic fluorine (AOF) and PFAS-bound fluorine"
    },
    {
      "endpoint_type": "mineralization",
      "evidence_locator_ids": [
        "S07-E06",
        "S07-E08"
